import heapq


def _quota_intervals(data, capacity, tie):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    if mandatory & blocked or len(mandatory) > k:
        return {"error": "impossible"}
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for chosen in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        valid = True
        for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > capacity:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and
                 (ids < best_ids if tie == "smallest" else ids > best_ids))):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _build_quota_solver(capacity, tie):
    return lambda data: _quota_intervals(data, capacity, tie)


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        choices.append([None] + packages[name])

    best_vector = None
    best_versions = None
    for selection in product(*choices):
        chosen = {name: row for name, row in zip(names, selection) if row is not None}
        versions = {name: row["version"] for name, row in chosen.items()}

        valid = True
        for name, (low, high) in roots.items():
            if name not in versions or not low <= versions[name] <= high:
                valid = False
                break
        if not valid:
            continue
        for name, version in versions.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
        if not valid:
            continue

        edges = {}
        reachable = set()
        pending = list(roots)
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            row = chosen.get(name)
            if row is None:
                valid = False
                break
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                version = versions.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or reachable != set(chosen):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True

        if not all(visit(name) for name in reachable):
            continue
        vector = tuple(versions.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best_versions = vector, versions

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bits.get(start, 0)
    initial_state = (start, initial_mask, data["coupons"])
    distances = {initial_state: data["start"]}
    queue = [(data["start"], start, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            next_mask = mask | bits.get(edge["v"], 0)
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_remaining))
    return {"arrival": None}


